"use strict";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useModalState } from "hooks/useModalState";
import { useManagedDeposits } from "hooks/useManagedDeposits";
import { useManagedVeABXRelays, useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useRelayStatuses } from "hooks/useManagedDeposits";
import { useVoterContract } from "hooks/useVoterContract";
import { useVotedLocks } from "hooks/useVotedLocks";
import { Flex, Text } from "ui/src";
import { QuestionInCircle } from "ui/src/components/icons";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { useAccount, useChainId } from "wagmi";
import RelayModal from "./RelayModal";
import SingleRelay from "./SingleRelay";
import SingleLock from "./SingleLock";
export default function Relays() {
  const { toggleModal: toggleRelayModal } = useModalState(ModalName.Relay);
  const { address: account } = useAccount();
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [rawChainId]);
  const {
    data: relays = [],
    isLoading: relaysLoading,
    error: relaysError
  } = useManagedVeABXRelays(true, resolvedChainId);
  const relayIds = useMemo(() => relays.map((relay) => relay.id), [relays]);
  const { statusMap, isLoading: statusesLoading } = useRelayStatuses(relayIds);
  const {
    data: userLocks = [],
    isLoading: locksLoading,
    refetch: refetchUserLocks
  } = useVeABXUserLocks(account, true, resolvedChainId);
  const {
    depositMap,
    isLoading: depositsLoading,
    refetch: refetchManagedStatus
  } = useManagedDeposits(userLocks || []);
  const { hasVoted } = useVotedLocks(userLocks || []);
  const { withdrawManaged, transactionState } = useVoterContract();
  const [pendingRelayAction, setPendingRelayAction] = useState(null);
  const locksByRelayId = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    (userLocks || []).forEach((lock) => {
      const managedInfo = depositMap.get(lock.id);
      if (managedInfo?.isDeposited && managedInfo.managedTokenId) {
        const current = map.get(managedInfo.managedTokenId) ?? [];
        current.push(lock);
        map.set(managedInfo.managedTokenId, current);
      }
    });
    return map;
  }, [userLocks, depositMap]);
  const handleWithdrawManaged = useCallback(
    async (params) => {
      setPendingRelayAction({
        lockId: params.tokenId,
        managedTokenId: params.managedTokenId,
        relayName: params.relayName
      });
      try {
        await withdrawManaged(params);
      } catch (error) {
        setPendingRelayAction(null);
        throw error;
      }
    },
    [withdrawManaged]
  );
  const isRelayActionInFlight = !!pendingRelayAction && (transactionState.isLoading || transactionState.isConfirming);
  useEffect(() => {
    if (!pendingRelayAction) {
      return;
    }
    if (transactionState.isSuccess) {
      refetchManagedStatus();
      refetchUserLocks();
      setPendingRelayAction(null);
    } else if (transactionState.error && !transactionState.isLoading && !transactionState.isConfirming) {
      setPendingRelayAction(null);
    }
  }, [
    pendingRelayAction,
    transactionState.isSuccess,
    transactionState.error,
    transactionState.isLoading,
    transactionState.isConfirming,
    refetchManagedStatus,
    refetchUserLocks
  ]);
  const relaysById = useMemo(() => new Map(relays.map((relay) => [relay.id, relay])), [relays]);
  const relayRenderOrder = useMemo(() => {
    const ids = /* @__PURE__ */ new Set();
    relays.forEach((relay) => ids.add(relay.id));
    locksByRelayId.forEach((_, relayId) => ids.add(relayId));
    const toBigInt = (value) => {
      try {
        return BigInt(value);
      } catch {
        return BigInt(Number.MAX_SAFE_INTEGER);
      }
    };
    return Array.from(ids).sort((a, b) => {
      const aValue = toBigInt(a);
      const bValue = toBigInt(b);
      if (aValue === bValue) {
        return a.localeCompare(b);
      }
      return aValue < bValue ? -1 : 1;
    });
  }, [relays, locksByRelayId]);
  const isLoading = relaysLoading || statusesLoading || locksLoading || depositsLoading;
  const renderRelays = () => {
    if (isLoading) {
      return <Flex centered py="$spacing24">
          <Text variant="body3" color="$neutral2">
            Loading ABX vault strategies…
          </Text>
        </Flex>;
    }
    if (relaysError) {
      return <Flex centered py="$spacing24">
          <Text variant="body3" color="$statusCritical">
            Failed to load ABX vault strategies
          </Text>
        </Flex>;
    }
    if (relayRenderOrder.length === 0) {
      return <Flex centered py="$spacing24">
          <Text variant="body3" color="$neutral2">
            No ABX vault strategies available right now.
          </Text>
        </Flex>;
    }
    return relayRenderOrder.map((relayId) => {
      const relay = relaysById.get(relayId);
      const depositedLocks = locksByRelayId.get(relayId) ?? [];
      const isActive = statusMap.get(relayId)?.isActive !== false;
      const shouldDisplay = isActive || depositedLocks.length > 0;
      if (!shouldDisplay) {
        return null;
      }
      return <Flex key={`relay-card-${relayId}`} flexDirection="column" gap="$gap12">
          {relay ? <SingleRelay relay={relay} isActive={isActive} /> : <Flex
        px="$spacing16"
        py="$spacing12"
        borderRadius="$rounded12"
        borderWidth={1}
        borderColor="$surface3"
        backgroundColor="$surface2"
      >
              <Text variant="buttonLabel3" color="$neutral1">
                ABX Vault #{relayId}
              </Text>
              <Text variant="body4" color="$neutral3">
                ABX Vault strategy
              </Text>
            </Flex>}

          {depositedLocks.length > 0 && <Flex flexDirection="column" gap="$gap16" ml="$spacing16">
              {depositedLocks.map((lock) => {
        const managedInfo = depositMap.get(lock.id);
        return <SingleLock
          key={`relay-lock-${lock.id}`}
          lock={lock}
          hasVoted={hasVoted(lock.id)}
          managedDeposit={managedInfo}
          relay={relay}
          onWithdrawManaged={managedInfo?.managedTokenId ? handleWithdrawManaged : void 0}
          isRelayActionPending={isRelayActionInFlight && pendingRelayAction?.lockId === lock.id}
          isActive={isActive}
        />;
      })}
            </Flex>}
        </Flex>;
    });
  };
  return <Flex marginTop={"$spacing36"}>
      <Flex className="top" row gap={"$spacing8"} alignItems="center">
        <Text variant={"heading3"}>Vaults</Text>
        <span
    style={{
      height: 17
    }}
    onClick={toggleRelayModal}
  >
          <QuestionInCircle
    color={"$neutral2"}
    cursor="pointer"
    hoverStyle={{ color: "$neutral3" }}
    size={"$icon.20"}
  />
        </span>
      </Flex>
      <Flex className="locks" mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        {renderRelays()}
      </Flex>
      <RelayModal />
    </Flex>;
}
