"use strict";
import { useMemo } from "react";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { useChainId, useReadContracts } from "wagmi";
export const REWARDS_DISTRIBUTOR_ABI = [
  {
    inputs: [
      {
        internalType: "uint256",
        name: "_tokenId",
        type: "uint256"
      }
    ],
    name: "claimable",
    outputs: [
      {
        internalType: "uint256",
        name: "claimable_",
        type: "uint256"
      }
    ],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [
      {
        internalType: "uint256",
        name: "_tokenId",
        type: "uint256"
      }
    ],
    name: "claim",
    outputs: [
      {
        internalType: "uint256",
        name: "",
        type: "uint256"
      }
    ],
    stateMutability: "nonpayable",
    type: "function"
  }
];
export function useVeABXRebaseClaimables(lockIds = [], overrideChainId) {
  const rawChainId = useChainId();
  const resolvedChainId = useMemo(() => {
    if (overrideChainId !== void 0) {
      return overrideChainId;
    }
    if (rawChainId === UniverseChainId.Mainnet || rawChainId === UniverseChainId.Sepolia) {
      return rawChainId;
    }
    return UniverseChainId.Mainnet;
  }, [overrideChainId, rawChainId]);
  const lockIdsKey = lockIds.join(",");
  const parsedLockIds = useMemo(() => {
    const seen = /* @__PURE__ */ new Set();
    const parsed = [];
    lockIds.forEach((id) => {
      if (!id || seen.has(id)) {
        return;
      }
      try {
        const tokenId = BigInt(id);
        parsed.push({ id, tokenId });
        seen.add(id);
      } catch (error) {
        console.warn("useVeABXRebaseClaimables: failed to parse lock id", id, error);
      }
    });
    return parsed;
  }, [lockIdsKey]);
  const rewardDistributor = getAbstractContracts(resolvedChainId)?.rewardDistributor;
  const contracts = useMemo(() => {
    if (!rewardDistributor || parsedLockIds.length === 0) {
      return [];
    }
    return parsedLockIds.map(({ tokenId }) => ({
      address: rewardDistributor,
      abi: REWARDS_DISTRIBUTOR_ABI,
      functionName: "claimable",
      args: [tokenId]
    }));
  }, [parsedLockIds, rewardDistributor]);
  const {
    data,
    isLoading,
    isFetching,
    refetch
  } = useReadContracts({
    contracts,
    query: {
      enabled: Boolean(rewardDistributor && contracts.length > 0),
      staleTime: 15e3,
      refetchInterval: 3e4,
      refetchOnWindowFocus: false,
      refetchOnMount: false
    }
  });
  const claimableMap = useMemo(() => {
    const map = /* @__PURE__ */ new Map();
    if (!parsedLockIds.length || !contracts.length) {
      return map;
    }
    parsedLockIds.forEach(({ id }, index) => {
      const result = data?.[index]?.result;
      map.set(id, result ?? 0n);
    });
    return map;
  }, [contracts.length, data, parsedLockIds]);
  return {
    claimableMap,
    isLoading,
    isFetching,
    refetch,
    hasMissingDistributor: !rewardDistributor
  };
}
